begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
set local role authenticated;
select set_config('request.jwt.claim.sub', '20000000-0000-4000-8000-000000000002', true);
select is((select count(*) from public.appointment_professional_names('10000000-0000-4000-8000-000000000001')), (select count(*) from public.appointments where center_id = '10000000-0000-4000-8000-000000000001'), 'member sees only their professional name');
with changed as (update public.appointments set patient_name = 'Updated' where id = '80000000-0000-4000-8000-000000000002' returning id) select is((select count(*) from changed), 1::bigint, 'member updates own appointment');
with changed as (update public.appointments set patient_name = 'Denied' where id = '80000000-0000-4000-8000-000000000001' returning id) select is((select count(*) from changed), 0::bigint, 'member cannot update another appointment');
with changed as (delete from public.appointments where id = '80000000-0000-4000-8000-000000000001' returning id) select is((select count(*) from changed), 0::bigint, 'member cannot delete another appointment');
select set_config('request.jwt.claim.sub', '20000000-0000-4000-8000-000000000003', true);
with changed as (update public.appointments set patient_name = 'Denied' where id = '80000000-0000-4000-8000-000000000003' returning id) select is((select count(*) from changed), 0::bigint, 'limited cannot update own appointment');
with changed as (delete from public.appointments where id = '80000000-0000-4000-8000-000000000003' returning id) select is((select count(*) from changed), 0::bigint, 'limited cannot delete own appointment');
select set_config('request.jwt.claim.sub', '20000000-0000-4000-8000-000000000001', true);
select is((select count(*) from public.appointment_professional_names('10000000-0000-4000-8000-000000000001')), (select count(*) from public.appointments where center_id = '10000000-0000-4000-8000-000000000001'), 'administrator sees center professional names');
with changed as (update public.appointments set patient_name = 'Admin update' where id = '80000000-0000-4000-8000-000000000003' returning id) select is((select count(*) from changed), 1::bigint, 'administrator updates center appointment');
with changed as (delete from public.appointments where id = '80000000-0000-4000-8000-000000000003' returning id) select is((select count(*) from changed), 1::bigint, 'administrator deletes center appointment');
select set_config('request.jwt.claim.sub', '20000000-0000-4000-8000-000000000004', true);
with changed as (delete from public.appointments where id = '80000000-0000-4000-8000-000000000002' returning id) select is((select count(*) from changed), 1::bigint, 'platform administrator deletes appointment');
select * from finish();
rollback;
